import * as T from './three.module.js';import {horsesFor,isAdultHorse} from './horses.js';import {createJockey} from './jockey.js';import {setAnimalMotion,animateRigDetails} from './animal-assets.js';
export function rideEligibility(state,id){const h=horsesFor(state).find(h=>h.id===id);if(!h)throw Error('This horse is not yours.');if(state.role!=='livestock')throw Error('Choose Livestock keeper before riding.');if(!isAdultHorse(h,state.day))throw Error('Foals must grow before being ridden.');if(h.pregnancyId)throw Error('This mare is resting during pregnancy.');if(h.energy<10)throw Error('Rest and care for this horse before riding.');return h;}
export function horseClear(x,z,heading,blocked){for(const along of [-1.05,0,1.05])for(const side of [-.48,0,.48])if(blocked(x+Math.sin(heading)*along+Math.cos(heading)*side,z+Math.cos(heading)*along-Math.sin(heading)*side))return false;return true;}
export function installFarmRiding({state,animals,player,keys,blocked,walk,isBusy,isDriving,clearRoute,toast}){let active=null,rider=null,pace='walk',elapsed=0,lastHint='',clock=0;const button=document.querySelector('#horse-interact'),hud=document.querySelector('#riding-hud');
 const nearest=()=>animals.filter(a=>a.type==='horse'&&a.model&&Math.hypot(a.g.position.x-player.position.x,a.g.position.z-player.position.z)<4).sort((a,b)=>a.g.position.distanceTo(player.position)-b.g.position.distanceTo(player.position))[0];
 function mount(a){try{rideEligibility(state,a.g.userData.appearanceKey);}catch(e){return toast(e.message);}if(isDriving())return toast('Park and exit your vehicle first.');if(Math.hypot(a.g.position.x-player.position.x,a.g.position.z-player.position.z)>4)return toast('The horse moved. Walk closer and try again.');clearRoute();active=a;a.ridden=true;rider=createJockey(state.avatar==='lady'?'#88718c':'#648389',1,state.avatar,4);rider.name='Farm riding avatar';a.g.add(rider);rider.userData.ready.catch(e=>toast('Rider model unavailable: '+e.message));player.visible=false;player.position.copy(a.g.position);window.home?.();toast('Mounted. W/S forward/back, A/D steer. R or Dismount to get down.');}
 window.rideFarmHorse=id=>{if(active)return toast('Dismount before changing horses.');if(isBusy())return toast('Finish or clear your task queue before riding.');if(isDriving())return toast('Park and exit your vehicle first.');try{rideEligibility(state,id);}catch(e){return toast(e.message);}const a=animals.find(a=>a.type==='horse'&&a.g.userData.appearanceKey===id);if(!a?.model)return toast('The horse model is still loading.');document.querySelector('dialog').close();if(Math.hypot(a.g.position.x-player.position.x,a.g.position.z-player.position.z)<4)return mount(a);const candidates=[];for(let i=0;i<16;i++){const t=i*Math.PI/8,x=a.g.position.x+Math.sin(t)*2.8,z=a.g.position.z+Math.cos(t)*2.8;if(!blocked(x,z))candidates.push({x,z});}candidates.sort((a,b)=>Math.hypot(a.x-player.position.x,a.z-player.position.z)-Math.hypot(b.x-player.position.x,b.z-player.position.z));if(!candidates.length)return toast('Open the stall gate and clear space beside the horse.');const g=candidates[0];walk(g.x,g.z,'Walk to mount horse',()=>mount(a));};
 window.dismountFarmHorse=()=>{if(!active)return;const a=active;let spot;for(let i=0;i<24;i++){const t=a.g.rotation.y+Math.PI/2+i*Math.PI/12,x=a.g.position.x+Math.sin(t)*2.1,z=a.g.position.z+Math.cos(t)*2.1;if(!blocked(x,z)&&!blocked(x+.3,z)&&!blocked(x-.3,z)&&!blocked(x,z+.3)&&!blocked(x,z-.3)){spot={x,z};break;}}if(!spot)return toast('Move the horse into clear space before dismounting.');a.g.remove(rider);rider=null;delete a.rideSeat;a.ridden=false;a.ridePark={x:a.g.position.x,z:a.g.position.z};if(a.ai){a.ai.x=a.g.position.x;a.ai.z=a.g.position.z;a.ai.heading=a.g.rotation.y;a.ai.bounds={minX:a.ai.x-3,maxX:a.ai.x+3,minZ:a.ai.z-3,maxZ:a.ai.z+3};a.ai.route=[];a.ai.wait=5;}player.position.set(spot.x,.2,spot.z);player.visible=true;active=null;hud&&(hud.hidden=true);toast('Dismounted. Your horse stays nearby.');};
 window.toggleFarmHorse=()=>active?window.dismountFarmHorse():nearest()&&window.rideFarmHorse(nearest().g.userData.appearanceKey);window.cycleRidingPace=()=>{pace=pace==='walk'?'trot':pace==='trot'?'canter':'walk';toast('Riding pace: '+pace);};window.addEventListener('keydown',e=>{if(e.repeat||document.querySelector('dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target?.tagName))return;if(e.key?.toLowerCase()==='r'){e.preventDefault();window.toggleFarmHorse();}});
 return {get active(){return active;},isMounted:()=>!!active,guard(){if(active){toast('Dismount before starting a farm task.');return true;}return false;},tick(dt){elapsed+=dt;clock+=dt;if(clock>.15){clock=0;const near=nearest();if(button){button.hidden=(!active&&!near)||document.querySelector('dialog').open;const text=active?'Dismount · R':'Ride '+(near?.g.userData.name||'horse')+' · R';if(text!==lastHint){button.textContent=text;lastHint=text;}}if(hud){hud.hidden=!active;const label=document.querySelector('#riding-readout');if(label&&active)label.textContent=active.g.userData.name+' · '+pace;}}if(!active)return;const a=active,open=document.querySelector('dialog').open,forward=open?0:(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),turn=open?0:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),speed=pace==='walk'?2.3:pace==='trot'?4.2:6.8,heading=a.g.rotation.y-turn*dt*(forward<0?-1:1)*1.6;if(horseClear(a.g.position.x,a.g.position.z,heading,blocked))a.g.rotation.y=heading;const move=forward*speed*dt*(forward<0?.45:1),nx=a.g.position.x+Math.sin(a.g.rotation.y)*move,nz=a.g.position.z+Math.cos(a.g.rotation.y)*move,clear=horseClear(nx,nz,a.g.rotation.y,blocked);if(clear){a.g.position.x=nx;a.g.position.z=nz;}const moving=forward&&clear;setAnimalMotion(a,moving?(pace==='canter'?'gallop':'walk'):'idle',moving?speed:0);a.mixer?.update(dt);animateRigDetails(a,dt);const body=a.model?.getObjectByName('Body');if(body&&rider){a.g.updateMatrixWorld(true);const seat=a.g.worldToLocal(body.getWorldPosition(new T.Vector3()));if(!a.rideSeat)a.rideSeat=seat.clone();rider.position.y=seat.y-a.rideSeat.y;}rider?.userData.update(elapsed,moving?speed/7:0,{steer:-turn,phase:a.currentAction?(a.currentAction.time/a.currentAction.getClip().duration)%1:0,delta:dt});player.position.copy(a.g.position);player.rotation.y=a.g.rotation.y;player.visible=false;a.g.visible=true;}};
}
